import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, uv, texture, positionLocal, normalLocal, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    CircleGeometry,
    MeshStandardMaterial,
    Vector3,
    Color,
    PointLight
  } = THREE;

  const root = new Group();
  root.name = 'quote-panel';
  root.userData = root.userData || {};

  const timelines = [];
  const primitiveCleanups = [];
  const resources = [];
  let disposed = false;

  const visualSpec = config.intent?.visualSpec || {};
  const colors = visualSpec.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const backdropGeometry = new PlaneGeometry(7, 6, 1, 1);
  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    color(colors.surface),
    color(colors.ink),
    uv().y
  );
  backdropMaterial.transparent = true;
  backdropMaterial.opacity = 0.96;

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'quote-stage-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const shadowGeometry = new CircleGeometry(1.7, 48);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 0.5,
    depthWrite: false
  });
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.name = 'quote-contact-shadow';
  shadow.scale.set(1.7, 0.55, 1);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.02, -0.72);
  root.add(shadow);
  resources.push(shadowGeometry, shadowMaterial);

  const panelGroup = new Group();
  panelGroup.name = 'quote-depth-panel';
  root.add(panelGroup);

  const backingGeometry = new BoxGeometry(3.35, 2.15, 0.16, 4, 4, 2);
  const backingMaterial = new MeshStandardNodeMaterial();
  backingMaterial.colorNode = color(colors.ink);
  backingMaterial.metalness = 0.48;
  backingMaterial.roughness = 0.58;
  backingMaterial.clearcoat = 0.18;

  const backing = new Mesh(backingGeometry, backingMaterial);
  backing.name = 'machined-metal-backing';
  backing.position.z = -0.08;
  panelGroup.add(backing);
  resources.push(backingGeometry, backingMaterial);

  const imageGeometry = new PlaneGeometry(3.12, 1.95, 64, 64);
  const imageMaterial = new MeshStandardNodeMaterial();
  imageMaterial.colorNode = color(colors.paper);
  imageMaterial.metalness = 0.18;
  imageMaterial.roughness = 0.62;
  imageMaterial.clearcoat = 0.16;
  imageMaterial.positionNode = positionLocal;
  imageMaterial.transparent = true;

  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.name = 'quote-parallax-image';
  imagePlane.position.z = 0.035;
  panelGroup.add(imagePlane);
  resources.push(imageGeometry, imageMaterial);

  const accentGeometry = new BoxGeometry(3.2, 0.035, 0.035, 2, 1, 1);
  const accentMaterial = new MeshStandardNodeMaterial();
  accentMaterial.colorNode = color(colors.accent);
  accentMaterial.emissiveNode = color(colors.accent);
  accentMaterial.emissiveIntensity = 1.35;
  accentMaterial.metalness = 0.28;
  accentMaterial.roughness = 0.5;

  const accentBar = new Mesh(accentGeometry, accentMaterial);
  accentBar.name = 'signal-red-rim';
  accentBar.position.set(0, -1.07, 0.12);
  panelGroup.add(accentBar);
  resources.push(accentGeometry, accentMaterial);

  const keyLight = new PointLight(colors.paper, 1.05, 7, 2);
  keyLight.position.set(2.4, 2.8, 3.2);
  panelGroup.add(keyLight);

  const rimLight = new PointLight(colors.accent, 0.72, 5, 2);
  rimLight.position.set(-2.2, 0.5, 2.6);
  panelGroup.add(rimLight);

  const textItems = config.textContent ?? visualSpec.textContent ?? [];
  for (const item of textItems) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.role === 'accent' ? colors.accent : colors.paper,
      align: item.typography?.align || 'left',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });

    textObject.position.set(
      item.position?.x ?? -1.15,
      item.position?.y ?? 0,
      item.position?.z ?? 0.16
    );
    panelGroup.add(textObject);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((imageTexture) => {
      if (disposed) return;
      imageTexture.colorSpace = THREE.SRGBColorSpace;
      imageMaterial.map = imageTexture;
      imageMaterial.needsUpdate = true;
      resources.push(imageTexture);
    }).catch(() => {});
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTexture) => {
      if (disposed) return;

      depthTexture.colorSpace = THREE.NoColorSpace;
      const depthNode = texture(depthTexture);
      imageMaterial.positionNode = positionLocal.add(
        normalLocal.mul(depthNode.r.sub(float(0.5)).mul(float(0.16)))
      );
      imageMaterial.needsUpdate = true;
      resources.push(depthTexture);
    }).catch(() => {});
  }

  for (const primitive of config.cinematicPrimitives || []) {
    if (!primitive?.name || typeof ctx.primitives?.[primitive.name] !== 'function') {
      continue;
    }

    const result = ctx.primitives[primitive.name](
      root,
      primitive.params || {}
    );

    if (result?.timeline) timelines.push(result.timeline);
    if (typeof result?.cleanup === 'function') {
      primitiveCleanups.push(result.cleanup);
    }
  }

  panelGroup.scale.setScalar(0.96);
  const entrance = gsap.timeline();
  entrance.to(panelGroup.position, {
    y: 0.4,
    duration: 0
  });
  entrance.to(panelGroup.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out'
  });
  entrance.to(panelGroup.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.34,
    ease: 'power4.out'
  }, '<0.18');
  entrance.to(panelGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.56,
    ease: 'power4.out'
  });
  timelines.push(entrance);

  let hoverTimeline = null;

  root.userData.handlers = {
    hover: (active) => {
      if (hoverTimeline) hoverTimeline.kill();

      hoverTimeline = gsap.timeline();
      if (active) {
        hoverTimeline.to(panelGroup.position, {
          y: 0.15,
          duration: 0.3,
          ease: 'power2.out'
        });
      } else {
        hoverTimeline.to(panelGroup.position, {
          y: 0,
          duration: 0.3,
          ease: 'power2.out'
        });
      }

      timelines.push(hoverTimeline);
    },

    click: () => {
      const press = gsap.timeline();
      press.to(panelGroup.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out'
      });
      press.to(panelGroup.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.38,
        ease: 'back.out(2)'
      });
      timelines.push(press);

      ctx.emit('hub-home.select', {
        node: 'quote-panel',
        parent: 'hub-home'
      });
    }
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const cleanup of primitiveCleanups) {
      cleanup();
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();

      const material = object.material;
      if (Array.isArray(material)) {
        for (const entry of material) entry?.dispose?.();
      } else {
        material?.dispose?.();
      }
    });

    for (const resource of resources) {
      resource?.dispose?.();
    }
  };

  return root;
}
